package com.nextrade.domain.ledger; import com.nextrade.common.enumtype.LedgerEntryType; import com.nextrade.common.identifier.*; import com.nextrade.common.valueobject.*; public record Release(LedgerEntry entry) { public Release { if(entry.type()!=LedgerEntryType.RELEASE) throw new IllegalArgumentException("Wrong ledger type"); } public static Release of(UserId user,Money amount,String reference){ return new Release(new LedgerEntry(LedgerEntryId.generate(),user,LedgerEntryType.RELEASE,amount,reference,java.time.Instant.now())); } }